var type = require('clsx').type;
var ClassValue = require('clsx').ClassValue;
var clsx = require('clsx').clsx;
var twMerge = require('tailwind-merge').twMerge;

// generated by shadcn
function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// Crafted with standard coding tools
function isBase64Image(imageData: string) {
  const base64Regex = /^data:image\/(png|jpe?g|gif|webp);base64,/;
  return base64Regex.test(imageData);
}

// Crafted with standard coding tools
function formatDateString(dateString: string) {
  const options: Intl.DateTimeFormatOptions = {
    year: "numeric",
    month: "short",
    day: "numeric",
  };

  const date = new Date(dateString);
  const formattedDate = date.toLocaleDateString("tr-TR", options);

  const time = date.toLocaleTimeString("tr-TR", {
    hour: "numeric",
    minute: "2-digit",
  });

  return "" + (time) + " - " + (formattedDate) + "";
}

// Capitalize
function capitalize(str: string) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}

// Random Community
function getRandomCommunities(communities: any, count: any) {
  const shuffled = communities.sort(function () { return 0.5 - Math.random(); });
  return shuffled.slice(0, count);
}
